import * as React from "react";

export type CoinSlotIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CoinSlotIcon({ size = 20, ...props }: CoinSlotIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx={12} cy={13} r={7.5} />
      <path d="M9 13h6" />
    </svg>
  );
}
